import networkx as nx
import itertools

def total_domination_number(G):
    # min size of S such that every v in V has a neighbor in S
    nodes = list(G.nodes())
    n = len(nodes)
    adj = {u: set(G.neighbors(u)) for u in nodes}
    # check if any isolated vertex
    if any(len(adj[u]) == 0 for u in nodes):
        return None
    for k in range(1, n + 1):
        for S in itertools.combinations(nodes, k):
            S_set = set(S)
            # every v in V must have neighbor in S
            if all(adj[v] & S_set for v in nodes):
                return k
    return 0

def roman_domination_number(G):
    # min sum f(v) where f: V -> {0, 1, 2} such that if f(v)==0 then neighbor has f(u)==2
    nodes = list(G.nodes())
    n = len(nodes)
    adj = {u: set(G.neighbors(u)) for u in nodes}
    # We want min sum. Possible sums: 0 to 2*n
    # A roman dominating function can be thought of as (V0, V1, V2) partition.
    # weight is |V1| + 2|V2|.
    best = 2 * n
    # We can iterate over all assignments or iterate by weight
    for f in itertools.product([0, 1, 2], repeat=n):
        w = sum(f)
        if w >= best:
            continue
        mapping = dict(zip(nodes, f))
        valid = True
        for v in nodes:
            if mapping[v] == 0:
                if not any(mapping[u] == 2 for u in adj[v]):
                    valid = False
                    break
        if valid:
            best = w
    return best

